function spawnObject(){let n=Math.random(),laneN=Math.floor(Math.random()*3);if(n<.47){objects.push({type:'coin',lane:laneN,z:1,phase:rand(0,8)});return}let type=n<.72?'car':'barrier';objects.push({type,lane:laneN,z:1});if(Math.random()<.14){let other=(laneN+1+Math.floor(Math.random()*2))%3;objects.push({type:'coin',lane:other,z:1.04,phase:rand(0,8)})}}
function update(dt){if(state!=='playing')return;speed=Math.min(1.25,speed+dt*.035);world+=dt*(140+speed*140);score+=dt*(15+speed*18);spawn-=dt;if(spawn<=0){spawnObject();spawn=rand(.55,1.05)/(.7+speed*.32)}
lane+=(targetLane-lane)*Math.min(1,dt*10);for(let o of objects){o.z-=dt*(.25+speed*.105);if(o.type==='coin'&&o.z<.115&&o.z>.04&&Math.abs(o.lane-lane)<.42){o.z=-2;coins++;coinsEl.textContent='◈ '+coins}}
for(let o of objects){if(o.type!=='coin'&&o.z<.10&&o.z>.03&&Math.abs(o.lane-lane)<.43){endGame();break}}objects=objects.filter(o=>o.z>-.08);flash=Math.max(0,flash-dt*2.7);scoreEl.textContent=String(Math.floor(score)).padStart(5,'0')}
function startGame(){state='playing';world=0;speed=.15;score=0;coins=0;lane=targetLane=1;objects=[];spawn=.9;flash=0;coinsEl.textContent='◈ 0';scoreEl.textContent='00000';overlay.classList.add('hidden');$('pause').textContent='Ⅱ';last=performance.now()}
function endGame(){if(state!=='playing')return;state='over';flash=1;best=Math.max(best,Math.floor(score));localStorage.setItem('neonRunBest',best);bestEl.textContent=String(best).padStart(5,'0');$('eyebrow').textContent='THE ROAD IS STILL OUT THERE';$('title').innerHTML='NICE<br><em>RIDE</em>'; $('message').textContent=`You made it ${Math.floor(score)} meters and found ${coins} light shard${coins===1?'':'s'}. Ready to beat your best?`;$('play').innerHTML='RIDE AGAIN&nbsp; →';$('hint').textContent='BEST DISTANCE: '+String(best).padStart(5,'0');overlay.classList.remove('hidden')}
function togglePause(){if(state==='playing'){state='paused';$('eyebrow').textContent='TAKE A BREATH';$('title').innerHTML='PAUSE<em>.</em>'; $('message').textContent='The road can wait. Your run is safely paused.';$('play').textContent='KEEP RIDING';$('hint').textContent='TAP RESUME WHEN YOU’RE READY';overlay.classList.remove('hidden');$('pause').textContent='▶'}else if(state==='paused'){state='playing';overlay.classList.add('hidden');$('pause').textContent='Ⅱ';last=performance.now()}}
$('play').addEventListener('click',()=>{if(state==='paused')togglePause();else startGame()});$('pause').addEventListener('click',()=>{if(state==='playing'||state==='paused')togglePause()});
function steer(dir){if(state==='playing')targetLane=clamp(targetLane+dir,0,2)}
$('left').addEventListener('pointerdown',e=>{e.preventDefault();steer(-1);$('left').classList.add('down')});$('left').addEventListener('pointerup',()=> $('left').classList.remove('down'));$('left').addEventListener('pointercancel',()=> $('left').classList.remove('down'));
$('right').addEventListener('pointerdown',e=>{e.preventDefault();steer(1);$('right').classList.add('down')});$('right').addEventListener('pointerup',()=> $('right').classList.remove('down'));$('right').addEventListener('pointercancel',()=> $('right').classList.remove('down'));
addEventListener('keydown',e=>{if(['ArrowLeft','a','A'].includes(e.key)){e.preventDefault();steer(-1)}else if(['ArrowRight','d','D'].includes(e.key)){e.preventDefault();steer(1)}else if(e.key===' '){e.preventDefault();if(state==='ready'||state==='over')startGame();else togglePause()}else if(e.key==='Escape')togglePause()});
canvas.addEventListener('pointerdown',e=>{touchX=e.clientX});canvas.addEventListener('pointerup',e=>{if(touchX!==null&&state==='playing'){let dx=e.clientX-touchX;if(Math.abs(dx)>24)steer(dx>0?1:-1)}touchX=null});
function frame(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;if(state==='playing')update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
})();
</script>
</body>
</html>

